import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1785319710000}`),a={name:`guide/privacy.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p>Sudoku is an offline-first application with optional cloud features. This page explains what (if any) data the app collects and how it is used.</p><h2 id="offline-core-—-no-data-collection-for-gameplay" tabindex="-1">Offline Core — No Data Collection for Gameplay <a class="header-anchor" href="#offline-core-—-no-data-collection-for-gameplay" aria-label="Permalink to “Offline Core — No Data Collection for Gameplay”">​</a></h2><ul><li>The core puzzle game is fully playable offline. No network access is required to play.</li><li>All game data — settings, game state, pencil notes, and statistics — is stored locally on your device.</li><li>There are no ads, no analytics, and no third-party tracking SDKs.</li></ul><h2 id="optional-cloud-features" tabindex="-1">Optional Cloud Features <a class="header-anchor" href="#optional-cloud-features" aria-label="Permalink to “Optional Cloud Features”">​</a></h2><h3 id="icloud-sync-cloudkit" tabindex="-1">iCloud Sync (CloudKit) <a class="header-anchor" href="#icloud-sync-cloudkit" aria-label="Permalink to “iCloud Sync (CloudKit)”">​</a></h3><p>When you sign in to iCloud and enable sync:</p><ul><li>Game saves, statistics, settings, and daily challenge progress are synced to your personal <strong>iCloud account</strong> via Apple&#39;s CloudKit service.</li><li>Data is encrypted in transit and at rest by Apple&#39;s infrastructure.</li><li>Only you can access your synced data using your Apple ID.</li><li>This feature is entirely optional — the app works perfectly without it.</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>When you sign in to Game Center:</p><ul><li>Leaderboard scores (best completion times per difficulty) may be shared on public leaderboards.</li><li>Achievement progress is recorded by Apple&#39;s Game Center service.</li><li>Your Game Center display name is visible to other players on leaderboards.</li><li>This feature is entirely optional.</li></ul><h2 id="the-only-other-network-access-more-apps" tabindex="-1">The Only Other Network Access: &quot;More Apps&quot; <a class="header-anchor" href="#the-only-other-network-access-more-apps" aria-label="Permalink to “The Only Other Network Access: &quot;More Apps&quot;”">​</a></h2><p>The sole non-cloud network feature is an optional <strong>&quot;More Apps&quot;</strong> section in Settings, which fetches a list of sibling apps from our servers. This feature:</p><ul><li>Only activates when you navigate to Settings → More Apps.</li><li>Fetches a lightweight list of app names and links — no personal data is sent or stored.</li><li>Can be completely ignored and does not affect gameplay in any way.</li></ul><h2 id="what-we-do-not-collect" tabindex="-1">What We Do Not Collect <a class="header-anchor" href="#what-we-do-not-collect" aria-label="Permalink to “What We Do Not Collect”">​</a></h2><ul><li>We do not collect personal information, files, images, or browsing history.</li><li>We do not send any game data to external servers (except as described above for iCloud/Game Center).</li><li>We do not include third-party analytics or advertising SDKs.</li><li>We do not use crash reporting or telemetry services.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><p>Sudoku requires minimal permissions:</p><ul><li><strong>iCloud</strong> (optional): For syncing game data across devices via CloudKit.</li><li><strong>Game Center</strong> (optional): For leaderboards and achievements.</li><li><strong>Network</strong> (optional): For iCloud sync, Game Center, and &quot;More Apps&quot;.</li></ul><p>No location, contacts, camera, microphone, or other privacy-sensitive permissions are requested.</p><h2 id="data-retention" tabindex="-1">Data Retention <a class="header-anchor" href="#data-retention" aria-label="Permalink to “Data Retention”">​</a></h2><ul><li>Local data remains on your device until you uninstall the app or reset it.</li><li>iCloud-synced data follows Apple&#39;s iCloud data retention policies.</li><li>Game Center data follows Apple&#39;s Game Center policies.</li></ul><h2 id="privacy-requests" tabindex="-1">Privacy Requests <a class="header-anchor" href="#privacy-requests" aria-label="Permalink to “Privacy Requests”">​</a></h2><p>Since Sudoku stores all data locally (and optionally in your personal iCloud), there is no server-side data that we control or access. To clear all app data:</p><ul><li><strong>Uninstall the app</strong> from your device(s).</li><li><strong>Reset iCloud data</strong>: In Settings → [Your Name] → iCloud → Manage Account Storage → Sudoku → Delete Data.</li><li><strong>Mac local reset</strong>: See the Troubleshooting guide for container removal instructions.</li></ul><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to “Children&#39;s Privacy”">​</a></h2><p>Sudoku does not actively collect personal information from anyone, including children. The app does not require accounts, chat features, or social networking.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>For privacy questions, open an issue at the project repository (<a href="https://github.com/sudoku-pro/sudoku-site" target="_blank" rel="noreferrer">https://github.com/sudoku-pro/sudoku-site</a>) or contact us at <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};